  · 第 1 列的第 i 行（i > m）放 i：它只当行最小（该列最小是 1）；
  · 第 1 行的第 j 列（j > m）放 n + j - m：它只当列最小（该行最小是 1）；
  · 其余格子从 2n - m + 1 开始顺次填大数。
此时 f(A) = [1, 2n-m]，恰好 k 个数。
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n, k;
        cin >> n >> k;
        if (k < n || k > 2 * n - 1) {          // 可行区间之外无解
            cout << -1 << '\n';
            continue;
        }
        int m = 2 * n - k;                      // 公共最小值个数（交集大小）
