// E. Skibidus and Rizz
// 构造 + 前缀和极差
//
// 把 0 看成 +1、1 看成 -1，则子串的 balance = 该段前缀和之差的绝对值（即 |x-y|）。
// 「所有子串 balance 的最大值」= 前缀和序列的 (最大值 - 最小值)，因为 P_0 = 0 一定在序列里。
// 记多数派字符的个数 A、少数派 B（若 n >= m 就让 up='0'，否则 up='1'，两者对称）。
// 可行 ⟺ |n-m| <= k <= max(n,m)：
//   · k >= |n-m|：整串自己就是一个 balance = |n-m| 的子串，最大值不会更小；
//   · k <= max(n,m)：某个子串要有 balance k，它里面至少有 k 个同一种字符，而任一种字符总数就那么多。
// 构造（以 up 为上升步）：
//   up^k 先爬到 k，再用 (down up)^(A-k) 在 k-1 与 k 之间来回，最后 down^(B-(A-k)) 一路降回 A-B。
//   路径始终落在 [A-B, k] 内（A-B >= 0），因此极差恰好是 k。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关掉 cin/cout 与 stdio 的同步
    cin.tie(nullptr);              // 解开 cin 与 cout 的绑定

    int t;
    cin >> t;                      // 数据组数
    while (t--) {
        int n, m, k;
        cin >> n >> m >> k;        // n 个 0、m 个 1，要求最大 balance 恰好为 k

        // 选出「多数派」当上升步：n >= m 时 0 是上升步，否则 1 是上升步
        char up, down;
        int A, B;                  // A = 上升步总数，B = 下降步总数
        if (n >= m) { up = '0'; down = '1'; A = n; B = m; }
        else        { up = '1'; down = '0'; A = m; B = n; }

        if (k > A || k < A - B) {  // 两条必要条件都验一遍，不满足就无解
            cout << -1 << '\n';
            continue;
        }

        string s;
        s.append(k, up);                                  // up^k：一路升到 k
        for (int i = 0; i < A - k; i++) {                 // (down up)^(A-k)：原地来回，不越界
            s.push_back(down);
            s.push_back(up);
        }
        s.append(B - (A - k), down);                      // 剩下的下降步一路降回 A-B

        cout << s << '\n';
    }
    return 0;
}
```

### 易错点

前缀高度包括起点零；末尾高度通常大于零，不能把它误当整个过程的最低高度。
